const item = $input.first();

if (!item.binary?.Image_1 || !item.binary?.Image_2) {
  throw new Error('Both images are required. Check the binary property names.');
}

const image1 = await this.helpers.getBinaryDataBuffer(0, 'Image_1');
const image2 = await this.helpers.getBinaryDataBuffer(0, 'Image_2');

return [{
  json: {
    image1: `data:${item.binary.Image_1.mimeType};base64,${image1.toString('base64')}`,
    image2: `data:${item.binary.Image_2.mimeType};base64,${image2.toString('base64')}`,
    prompt: `Compare Image 1 and Image 2 directly. Carefully inspect the entire images, including corners, edges, and small details. Identify all differences, especially logos, brand marks, watermarks, text, added or missing objects, colours, shapes, positions, and layout. Explicitly check whether each logo is present in both images. Report an element as missing only when the images provide sufficient evidence. Do not invent findings. Return a structured comparison report with summary, overall similarity percentage, differences_found, differences with category, image_1_observation, image_2_observation, description, severity and confidence, unchanged_elements, and limitations.`
  }
}];

const response = $input.first().json;

const text = response.output
  ?.flatMap(item => item.content || [])
  ?.find(content => content.type === 'output_text')
  ?.text;

if (!text) {
  throw new Error('No comparison report found in the OpenAI response.');
}

const cleaned = text
  .replace(/^```json\s*/i, '')
  .replace(/\s*```$/, '')
  .trim();

let report;

try {
  report = JSON.parse(cleaned);
} catch {
  report = {
    summary: cleaned,
    overall_similarity: null,
    differences_found: true,
    differences: [],
    unchanged_elements: [],
    limitations: ['The AI response was not valid JSON.']
  };
}

return [{ json: report }];

